const money = (value:number) => `${value < 0 ? "−" : ""}₭${Math.abs(value).toLocaleString("en-US")}`;

function Metric({label,value,detail,tone}:{label:string;value:string|number;detail:string;tone?:string}) {
  return <article><small>{label}</small><b>{value}</b><span data-tone={tone}>{detail}</span></article>;
}

type AdminSelectOption={value:string;label:string;meta?:string};
function AdminSelect({value,defaultValue,options,onChange,ariaLabel}:{value?:string;defaultValue?:string;options:AdminSelectOption[];onChange?:(value:string)=>void;ariaLabel:string}) {
  const [internalValue,setInternalValue]=useState(defaultValue??options[0]?.value??"");
  const [open,setOpen]=useState(false);
  const current=value??internalValue;
  const selectedIndex=Math.max(0,options.findIndex(option=>option.value===current));
  const [highlighted,setHighlighted]=useState(selectedIndex);
  const rootRef=useRef<HTMLDivElement>(null);
  const listId=useId();
  useEffect(()=>{const close=(event:PointerEvent)=>{if(!rootRef.current?.contains(event.target as Node))setOpen(false)};document.addEventListener("pointerdown",close);return()=>document.removeEventListener("pointerdown",close)},[]);
  const choose=(option:AdminSelectOption)=>{setInternalValue(option.value);onChange?.(option.value);setHighlighted(options.findIndex(item=>item.value===option.value));setOpen(false)};
  const keyDown=(event:ReactKeyboardEvent<HTMLButtonElement>)=>{if(event.key==="Escape"){setOpen(false);return}if(event.key==="ArrowDown"||event.key==="ArrowUp"){event.preventDefault();const direction=event.key==="ArrowDown"?1:-1;const next=(highlighted+direction+options.length)%options.length;setHighlighted(next);setOpen(true);return}if((event.key==="Enter"||event.key===" ")&&open){event.preventDefault();choose(options[highlighted]);return}if(event.key==="Home"||event.key==="End"){event.preventDefault();const next=event.key==="Home"?0:options.length-1;setHighlighted(next);setOpen(true)}};
  const selected=options[selectedIndex]??options[0];
  return <div className={styles.adminSelect} ref={rootRef}><button type="button" className={styles.adminSelectTrigger} aria-label={ariaLabel} aria-haspopup="listbox" aria-expanded={open} aria-controls={listId} onClick={()=>{setHighlighted(selectedIndex);setOpen(state=>!state)}} onKeyDown={keyDown}><span><b>{selected?.label}</b>{selected?.meta?<small>{selected.meta}</small>:null}</span><i aria-hidden="true">⌄</i></button>{open?<div className={styles.adminSelectMenu} id={listId} role="listbox" aria-label={ariaLabel}>{options.map((option,index)=><button type="button" role="option" aria-selected={option.value===current} data-highlighted={index===highlighted} key={option.value} onMouseEnter={()=>setHighlighted(index)} onClick={()=>choose(option)}><span><b>{option.label}</b>{option.meta?<small>{option.meta}</small>:null}</span>{option.value===current?<i aria-hidden="true">✓</i>:null}</button>)}</div>:null}</div>;
}

type CreatePayload = {name:string;type:string;contact:string;detail:string};

function QuickCreate({kind,onClose,onCreate}:{kind:string;onClose:()=>void;onCreate:(payload:CreatePayload)=>void}) {
  const [name,setName] = useState("");
  const [type,setType] = useState("");
  const [contact,setContact] = useState("");
  const [detail,setDetail] = useState("");
  const lower=kind.toLowerCase();
  const preset=lower.includes("partner")
    ? {name:"ຊື່ທຸລະກິດ",type:"ປະເພດທຸລະກິດ",contact:"ຜູ້ຕິດຕໍ່ / ເບີໂທ",detail:"Next action ແລະ Lead source"}
    : lower.includes("campaign")
      ? {name:"ຊື່ Campaign",type:"Partner / ຮ້ານ",contact:"Owner",detail:"Objective, ວັນເລີ່ມ ແລະງົບ"}
      : lower.includes("user")
        ? {name:"ຊື່ຜູ້ໃຊ້",type:"Role",contact:"Email / ເບີໂທ",detail:"Module scope ແລະວັນໝົດອາຍຸ"}
        : lower.includes("ທຸລະກຳ")
          ? {name:"Counterparty",type:"ປະເພດ: Payment / Expense",contact:"Amount ແລະວັນທີ",detail:"Bank reference / ຫຼັກຖານ"}
          : {name:"ຊື່ ຫຼືຫົວຂໍ້",type:"ປະເພດວຽກ",contact:"Owner / ຜູ້ຕິດຕໍ່",detail:"ລາຍລະອຽດ ແລະກຳນົດເວລາ"};
  const submit = (event:FormEvent) => { event.preventDefault(); if(name.trim()&&type.trim()) onCreate({name:name.trim(),type:type.trim(),contact:contact.trim(),detail:detail.trim()}); };
  return <div className={styles.modalBackdrop} role="presentation"><section className={`${styles.modal} ${styles.createModal}`} role="dialog" aria-modal="true" aria-labelledby="create-title"><header><div><small>CREATE · REQUIRED INFORMATION</small><h2 id="create-title">{kind}</h2></div><button onClick={onClose} aria-label="ປິດ">×</button></header><form onSubmit={submit}><div className={styles.createGrid}><label>{preset.name} <em>*</em><input autoFocus value={name} onChange={event=>setName(event.target.value)} placeholder={preset.name}/></label><label>{preset.type} <em>*</em><input value={type} onChange={event=>setType(event.target.value)} placeholder={preset.type}/></label><label>{preset.contact}<input value={contact} onChange={event=>setContact(event.target.value)} placeholder={preset.contact}/></label><label>{preset.detail}<textarea value={detail} onChange={event=>setDetail(event.target.value)} placeholder={preset.detail}/></label></div><p>ຊ່ອງທີ່ມີ * ຕ້ອງຄົບກ່ອນສ້າງ. Record ໃໝ່ຈະເລີ່ມໃນສະຖານະທີ່ປອດໄພ ແລະຍັງບໍ່ Publish ຫຼື Verified.</p><footer><button type="button" onClick={onClose}>ຍົກເລີກ</button><button className={styles.primary} disabled={!name.trim()||!type.trim()}>ສ້າງແລະເປີດ Record</button></footer></form></section></div>;
}

type IntakeMode = "choose"|"place"|"source";
type PlaceDraft = {name:string;category:string;address:string;phone:string};
type SourceDraft = {title:string;url:string;creator:string;platform:string;placeId:string};

function ContentIntakeWizard({initialMode,places,existingSources,onClose,onCreatePlace,onCreateSource}:{initialMode:IntakeMode;places:Place[];existingSources:Source[];onClose:()=>void;onCreatePlace:(draft:PlaceDraft)=>void;onCreateSource:(draft:SourceDraft)=>void}) {
  const [mode,setMode]=useState<IntakeMode>(initialMode);
  const [placeName,setPlaceName]=useState("");const [category,setCategory]=useState("ຮ້ານອາຫານ");const [address,setAddress]=useState("");const [phone,setPhone]=useState("");
  const [sourceTitle,setSourceTitle]=useState("");const [url,setUrl]=useState("");const [creator,setCreator]=useState("");const [placeId,setPlaceId]=useState(places[0]?.id??"");
  const platform=url.toLowerCase().includes("tiktok")?"TikTok":url.toLowerCase().includes("youtu")?"YouTube":url.toLowerCase().includes("facebook")||url.toLowerCase().includes("fb.")?"Facebook":"Social link";
  const duplicate=existingSources.find(source=>source.url&&source.url.trim().toLowerCase()===url.trim().toLowerCase());
  const supportedUrl=/^https:\/\/(www\.)?(tiktok\.com|youtube\.com|youtu\.be|facebook\.com|fb\.watch)\//i.test(url.trim());
  const submitPlace=(event:FormEvent)=>{event.preventDefault();if(placeName.trim()&&address.trim())onCreatePlace({name:placeName.trim(),category,address:address.trim(),phone:phone.trim()})};
  const submitSource=(event:FormEvent)=>{event.preventDefault();if(sourceTitle.trim()&&url.trim()&&placeId&&supportedUrl&&!duplicate)onCreateSource({title:sourceTitle.trim(),url:url.trim(),creator:creator.trim()||"Unknown creator",platform,placeId})};
  return <div className={styles.modalBackdrop} role="presentation"><section className={`${styles.modal} ${styles.intakeWizard}`} role="dialog" aria-modal="true" aria-labelledby="intake-title"><header><div><small>CONTENT INTAKE · GUIDED FLOW</small><h2 id="intake-title">{mode==="choose"?"ທ່ານຕ້ອງການເພີ່ມຫຍັງ?":mode==="place"?"ເພີ່ມຮ້ານ ຫຼືສະຖານທີ່":"ເພີ່ມ Link ວິດີໂອຣີວິວ"}</h2></div><button onClick={onClose} aria-label="Close">×</button></header>
    {mode==="choose"?<><p className={styles.wizardIntro}>ເລືອກຕາມສິ່ງທີ່ທ່ານມີຢູ່. “Place” ແມ່ນຂໍ້ມູນຮ້ານ/ສະຖານທີ່; “Review Source” ແມ່ນ Link ວິດີໂອທີ່ຈະຖືກຜູກເຂົ້າກັບ Place.</p><div className={styles.intakeChoices}><button onClick={()=>setMode("place")}><i>⌖</i><span><b>ເພີ່ມຮ້ານ / ສະຖານທີ່</b><small>ຮ້ານອາຫານ, ກາເຟ, ທີ່ພັກ, ບ່ອນທ່ອງທ່ຽວ ຫຼືບໍລິການ</small><em>ສ້າງ Place profile →</em></span></button><button onClick={()=>setMode("source")}><i>▶</i><span><b>ເພີ່ມວິດີໂອຣີວິວ</b><small>ວາງ Link ຈາກ TikTok, Facebook ຫຼື YouTube ແລ້ວເລືອກ Place</small><em>ສ້າງ Review Source →</em></span></button></div><div className={styles.intakeSequence}><span><b>1</b>ສ້າງ/ເລືອກ Place</span><i>→</i><span><b>2</b>ເພີ່ມ Link ຣີວິວ</span><i>→</i><span><b>3</b>ກວດ Rights</span><i>→</i><span><b>4</b>Publish</span></div></>:null}
    {mode==="place"?<form onSubmit={submitPlace}><div className={styles.wizardNotice}><b>ຂັ້ນຕອນ 1 ຈາກ 2 · ສ້າງ Place ກ່ອນ</b><span>ຫຼັງຈາກສ້າງ ລະບົບຈະພາໄປໜ້າ Places ເພື່ອຕື່ມຂໍ້ມູນ ແລະກວດກ່ອນ Publish.</span></div><div className={styles.wizardFields}><label>ຊື່ຮ້ານ ຫຼືສະຖານທີ່ <em>*</em><input autoFocus value={placeName} onChange={event=>setPlaceName(event.target.value)} placeholder="ຕົວຢ່າງ: ຮ້ານເຂົ້າປຽກແຄມຂອງ"/></label><label>ປະເພດ <em>*</em><AdminSelect ariaLabel="ເລືອກປະເພດ Place" value={category} onChange={setCategory} options={["ຮ້ານອາຫານ","ຮ້ານກາເຟ","ທີ່ພັກ / ໂຮງແຮມ","ສະຖານທີ່ທ່ອງທ່ຽວ","ກິດຈະກຳ / ທົວ","ບໍລິການທ້ອງຖິ່ນ"].map(item=>({value:item,label:item}))}/></label><label className={styles.full}>ທີ່ຢູ່ / ເມືອງ / ແຂວງ <em>*</em><textarea value={address} onChange={event=>setAddress(event.target.value)} placeholder="ລະບຸບ້ານ, ເມືອງ ແລະແຂວງ"/></label><label>ເບີໂທຕິດຕໍ່<input value={phone} onChange={event=>setPhone(event.target.value)} placeholder="+856 20 …"/></label></div><footer><button type="button" onClick={()=>setMode("choose")}>← ກັບໄປເລືອກ</button><button className={styles.primary} disabled={!placeName.trim()||!address.trim()}>ສ້າງ Place ແບບ Draft</button></footer></form>:null}
    {mode==="source"?<form onSubmit={submitSource}><div className={styles.wizardNotice}><b>ຂັ້ນຕອນ 2 ຈາກ 2 · ຜູກ Review Source ກັບ Place</b><span>Platform ຈະບັນທຶກ Link ເທົ່ານັ້ນ; ບໍ່ Download ຫຼື Re-upload ວິດີໂອ.</span></div><div className={styles.wizardFields}><label className={styles.full}>Link ວິດີໂອ <em>*</em><input autoFocus type="url" aria-invalid={Boolean(url)&&(!supportedUrl||Boolean(duplicate))} value={url} onChange={event=>setUrl(event.target.value)} placeholder="https://www.tiktok.com/…"/><small>ກວດພົບ Platform: <b>{platform}</b></small>{url&&!supportedUrl?<span className={styles.fieldError} role="alert">ຮອງຮັບ Link ຈາກ TikTok, Facebook ແລະ YouTube ເທົ່ານັ້ນ.</span>:null}{duplicate?<span className={styles.fieldError} role="alert">Link ນີ້ມີແລ້ວ: {duplicate.id} · {duplicate.title}</span>:null}</label><label>ຫົວຂໍ້ຣີວິວ <em>*</em><input value={sourceTitle} onChange={event=>setSourceTitle(event.target.value)} placeholder="ຕົວຢ່າງ: ຣີວິວເມນູຂາຍດີ"/></label><label>Creator / Channel<input value={creator} onChange={event=>setCreator(event.target.value)} placeholder="@creator"/></label><label className={styles.full}>ວິດີໂອນີ້ຣີວິວ Place ໃດ? <em>*</em><AdminSelect ariaLabel="ເລືອກ Place ສຳລັບວິດີໂອ" value={placeId} onChange={setPlaceId} options={places.map(place=>({value:place.id,label:place.name,meta:`${place.category} · ${place.id}`}))}/><small>ບໍ່ພົບ Place? <button type="button" className={styles.textAction} onClick={()=>setMode("place")}>ສ້າງ Place ກ່ອນ</button></small></label></div><footer><button type="button" onClick={()=>setMode("choose")}>← ກັບໄປເລືອກ</button><button className={styles.primary} disabled={!sourceTitle.trim()||!url.trim()||!placeId||!supportedUrl||Boolean(duplicate)}>ເພີ່ມ Source ເຂົ້າ Inbox</button></footer></form>:null}
  </section></div>;
}

